//! Offline ideal-hit matrix generated by the real Game::step/fire/hurt path.
//! This is explanatory data, never a match, reward or browser score authority.
use crate::{Config, Game, Input, Rules, HZ, MAX_TICKS};
use serde::Serialize;
#[derive(Serialize)]
pub struct Row {
    pub weapon: usize,
    pub hero: usize,
    pub armor: i32,
    pub head: bool,
    pub distance: u32,
    pub shield: bool,
    pub boost: u8,
    pub first_health_damage: i32,
    pub first_armor_damage: i32,
    pub rounds: u32,
    pub ttk_ticks: u32,
    pub reloads: u32,
}
pub fn case(
    rules: &Rules,
    weapon: usize,
    hero: usize,
    armor: i32,
    head: bool,
    distance: u32,
    shield: bool,
    boost: u8,
) -> Result<Row, String> {
    let mut r = rules.clone();
    r.maps[0].obstacles.clear();
    r.maps[0].extent = 10000.;
    // Every pellet is aimed at the selected region; dispersion/recoil are
    // deliberately removed for this ideal lower bound. All damage, armor,
    // effect expiration, burst, reload and reserve logic remains native.
    r.weapons[weapon].spread = 0.;
    let mut heroes = [0; 10];
    heroes[5] = hero;
    heroes[0] = if boost == 1 { 5 } else { 0 };
    let mut g = Game::new(
        Config {
            map: 0,
            mode: "deathmatch".into(),
            heroes,
            bots: [false; 10],
            difficulty: 1,
            seed: 2050,
        },
        &r,
    )?;
    g.phase = "live".into();
    g.phase_ticks = MAX_TICKS;
    for p in &mut g.players {
        p.alive = false;
        p.respawn = MAX_TICKS;
        p.protection = 0;
    }
    g.players[0].alive = true;
    g.players[0].position = [0., 0., distance as f64];
    g.players[0].weapon = weapon;
    g.players[0].overclock = if boost == 2 { HZ * 4 } else { 0 };
    g.players[0].effect = if boost == 1 { HZ * 5 } else { 0 };
    g.players[5].alive = true;
    g.players[5].position = [0.; 3];
    g.players[5].armor = armor;
    g.players[5].effect = if shield { HZ * 5 } else { 0 };
    let target_y = if head {
        r.hit_regions.standing.head_y
    } else {
        r.hit_regions.standing.body_lower
    };
    let pitch = ((target_y - 56.) / (distance as f64)).atan();
    let mut first = None;
    let mut first_health_damage = 0;
    let mut first_armor_damage = 0;
    let mut reloads = 0;
    for _ in 0..HZ * 300 {
        let p = &mut g.players[0];
        p.weapon_recoil = crate::recoil::State::default();
        let reload = p.ammo[weapon] == 0;
        let before_reload = p.reload;
        let before_shots = p.shots;
        let before_hp = g.players[5].health;
        let before_armor = g.players[5].armor;
        let mut inputs = [Input::default(); 10];
        inputs[0] = Input {
            fire: true,
            reload,
            scope: true,
            pitch,
            ..Input::default()
        };
        g.step(inputs, &r)?;
        if before_reload == 0 && g.players[0].reload > 0 {
            reloads += 1;
        }
        if first.is_none() && g.players[0].shots > before_shots {
            first = Some(g.tick);
            first_health_damage = before_hp - g.players[5].health;
            first_armor_damage = before_armor - g.players[5].armor;
        }
        if !g.players[5].alive {
            return Ok(Row {
                weapon,
                hero,
                armor,
                head,
                distance,
                shield,
                boost,
                first_health_damage,
                first_armor_damage,
                rounds: g.players[0].shots,
                ttk_ticks: g.tick - first.ok_or("Missing first shot")?,
                reloads,
            });
        }
    }
    Err(format!(
        "Ideal damage case did not finish: weapon={weapon} hero={hero}"
    ))
}
pub fn matrix(r: &Rules) -> Result<Vec<Row>, String> {
    let mut rows = vec![];
    for weapon in 0..r.weapons.len() {
        for hero in 0..r.heroes.len() {
            for armor in [0, r.heroes[hero].armor, 100] {
                for head in [false, true] {
                    for distance in [100, 600, 1500, 3000] {
                        for shield in [false, true] {
                            if shield && hero != 2 {
                                continue;
                            }
                            for boost in 0..3 {
                                rows.push(case(
                                    r, weapon, hero, armor, head, distance, shield, boost,
                                )?);
                            }
                        }
                    }
                }
            }
        }
    }
    Ok(rows)
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn native_matrix_covers_pellets_bursts_shield_break_reloads_and_expiration() {
        let r = Rules::load();
        assert_eq!(case(&r, 3, 0, 0, true, 100, false, 0).unwrap().rounds, 1);
        let pellets = case(&r, 4, 0, 0, false, 100, false, 0).unwrap();
        assert_eq!(pellets.rounds, 1);
        assert_eq!(pellets.ttk_ticks, 0);
        let burst = case(&r, 5, 1, 0, false, 100, false, 0).unwrap();
        assert_eq!(burst.rounds, 5);
        assert_eq!(
            burst.ttk_ticks,
            r.weapons[5].burst_interval * 3 + r.weapons[5].interval
        );
        let shield = case(&r, 8, 2, 100, false, 100, true, 0).unwrap();
        let plain = case(&r, 8, 2, 100, false, 100, false, 0).unwrap();
        assert!(
            shield.rounds >= plain.rounds && shield.rounds <= plain.rounds + 1,
            "EMP removes shield after the first hit"
        );
        let slow = case(&r, 11, 2, 100, false, 3000, true, 0).unwrap();
        assert!(slow.reloads > 0);
        assert!(slow.ttk_ticks > HZ * 5);
        assert!(
            case(&r, 2, 2, 100, false, 100, false, 1).unwrap().ttk_ticks
                < case(&r, 2, 2, 100, false, 100, false, 0).unwrap().ttk_ticks
        );
    }
}
